    return {"id": f"question-social-content-geo-bi-iv-2-{index}", "subject": "social", "type": "single-choice", "prompt": prompt, "options": opts, "knowledgeIds": ["kg-social-content-geo-bi-iv-2"], "difficulty": "medium", "answer": {"value": aid, "explanation": reason}, "provenance": {"origin": "original", "license": "All rights reserved", "sourceUrl": SOURCES[0][0], "sourceLocator": "高雄市立鹽埕國中三年級社會科公開段考；本題只研究公開試題能力結構與資料型態。", "authoringNote": "依官方課綱 KG 與三個公立學校公開來源的題型／能力方向，以移民與產業的新資料情境獨立改寫；未複製原文、選項、圖表或答案；待第二輪 AI／Terra 內容複核。"}, "reviewStatus": "draft", "updatedAt": "2026-09-09", "lessonId": "lesson-social-content-geo-bi-iv-2", "examPatternRefs": refs, "solutionStrategy": "先辨認人口移動的推力、拉力與制度，再對照產業需求、家庭與公共服務，最後限制結論的時間與空間尺度。", "solutionSteps": steps}

